#!/usr/bin/env python3
"""v41 : Chat, présentation uniquement (maquette Chat v3).
- Carte de rédaction du brief : icône et pastille d'état, erreur lisible (plus de bandeau collé aux bords),
  plus de bande grise vide pendant la rédaction, pied réservé au bouton principal,
  suggestions en petites puces « Ou modifier : » sous la carte (emoji de tête masqué à l'affichage seulement).
- « Je réfléchis… » et « Travail en cours… » ne s'affichent plus ensemble.
- Listes du texte de l'IA avec puces et retrait normal ; liens « Modifier » et « Lire tout » en couleur d'accent.
Mêmes boutons, mêmes actions, mêmes textes envoyés. Usage : python3 apply-v41.py [--check]"""
import sys, pathlib, json
CHECK = "--check" in sys.argv
R = json.loads(r'''[["src/routes/_authenticated/create.tsx", [["            <div className=\"gx-m-x\">\n            <div className=\"gx-kard gx-prompt animate-fade-in\">\n              {(() => {\n                const phase = briefCardPhase({ preparing: briefPreparing, streaming: streamingPrompt, error: prepareError });\n                return (\n              <>\n              <div className=\"gx-kh\">\n                <b>{briefCardTitle(phase)}</b>\n                <small>{briefCardSubtitle(phase)}</small>\n              </div>\n              {phase === \"loading\" ? (\n                <div className=\"gx-pp gx-pp-load\" aria-busy=\"true\" aria-label=\"Rédaction en cours\">\n                  <i /><i /><i />\n                </div>\n              ) : null}\n              {phase === \"streaming\" ? (\n                <div className=\"gx-pp gx-pp-stream\" aria-busy=\"true\">\n                  <BriefDisplay value={streamingPrompt} mediaType={String(state.mediaType ?? readyBrief?.mediaType ?? '')} streaming />\n                </div>\n              ) : null}\n              {phase === \"error\" ? (\n                <p className=\"gx-note\" role=\"alert\">{prepareError}</p>\n              ) : null}\n              </>\n                );\n              })()}\n              {readyBriefInfo?.notices.map((notice, index) => <p className=\"gx-note\" key={index}>{notice}</p>)}\n              {briefPreparing && promptSlow ? (\n                <p className=\"gx-note gx-c3-slow\"><Loader2 className=\"gx-i animate-spin\" />C’est un peu plus long que d’habitude.</p>\n              ) : null}\n              <div className=\"gx-kf\">\n                {!briefPreparing && (\n                  <button\n                    type=\"button\"\n                    className=\"gx-btn gx-sm gx-pri\"\n                    data-testid=\"brief-retry\"\n                    onClick={() => {\n                      const key = readyBriefInfo?.messageId ?? null;\n                      autoPreparedRef.current = key;\n                      setAttemptedBriefKey(key);\n                      setAutoPrepareFailed(false);\n                      void handlePreparePrompt().finally(() => setAutoPrepareFailed(true));\n                    }}\n                    disabled={generating}\n                  >\n                    {prepareError ? \"Réessayer\" : \"Rédiger le prompt\"}\n                    <ArrowRight className=\"gx-i\" />\n                  </button>\n                )}\n                {!briefPreparing && isClientChatV2Active() &&\n                  v2MessageSuggestions([...messages].reverse().find((x) => x.role === \"assistant\"))\n                    .filter((s) => !V2_LAUNCH_DUP_RE.test(s))\n                    .map((s) => (\n                      <button key={s} type=\"button\" className=\"gx-btn gx-sm\" onClick={() => handleSuggestion(s)} disabled={generating}>\n                        {s}\n                      </button>\n                    ))}\n              </div>\n\n            </div>\n            </div>\n          )}\n", "            <div className=\"gx-m-x\">\n            {(() => {\n              // Présentation seulement (maquette Chat v3) : en-tête avec icône et pastille d'état,\n              // erreur lisible, pied réservé au bouton principal, suggestions en petites puces sous la carte.\n              const phase = briefCardPhase({ preparing: briefPreparing, streaming: streamingPrompt, error: prepareError });\n              const isVideoBrief = String(state.mediaType ?? readyBrief?.mediaType ?? \"\") === \"video\";\n              const pill = phase === \"loading\" || phase === \"streaming\"\n                ? { cls: \"gx-c3-run\", label: \"Rédaction…\" }\n                : phase === \"error\" ? { cls: \"gx-c3-err\", label: \"Échec\" } : { cls: \"gx-c3-ok\", label: \"Prêt\" };\n              const mods = !briefPreparing && isClientChatV2Active()\n                ? v2MessageSuggestions([...messages].reverse().find((x) => x.role === \"assistant\")).filter((s) => !V2_LAUNCH_DUP_RE.test(s))\n                : [];\n              return (\n            <>\n            <div className=\"gx-kard gx-prompt gx-c3-bcard animate-fade-in\" data-phase={phase}>\n              <div className=\"gx-kh\">\n                <span className=\"gx-c3-head-icon\" aria-hidden>{isVideoBrief ? <Clapperboard className=\"gx-i\" /> : <Wand2 className=\"gx-i\" />}</span>\n                <b>{briefCardTitle(phase)}</b>\n                <span className=\"gx-kh-m\">{briefCardSubtitle(phase)}</span>\n                <span className={`gx-c3-status ${pill.cls}`}>{pill.label}</span>\n              </div>\n              {phase === \"loading\" ? (\n                <div className=\"gx-pp gx-pp-load\" aria-busy=\"true\" aria-label=\"Rédaction en cours\">\n                  <i /><i /><i />\n                </div>\n              ) : null}\n              {phase === \"streaming\" ? (\n                <div className=\"gx-pp gx-pp-stream\" aria-busy=\"true\">\n                  <BriefDisplay value={streamingPrompt} mediaType={String(state.mediaType ?? readyBrief?.mediaType ?? '')} streaming />\n                </div>\n              ) : null}\n              {phase === \"error\" ? (\n                <p className=\"gx-c3-detail\" role=\"alert\"><AlertTriangle className=\"gx-i\" aria-hidden />{prepareError}</p>\n              ) : null}\n              {readyBriefInfo?.notices.map((notice, index) => <p className=\"gx-note\" key={index}>{notice}</p>)}\n              {briefPreparing && promptSlow ? (\n                <p className=\"gx-note gx-c3-slow\"><Loader2 className=\"gx-i animate-spin\" />C’est un peu plus long que d’habitude.</p>\n              ) : null}\n              {!briefPreparing && (\n              <div className=\"gx-kf\">\n                  <button\n                    type=\"button\"\n                    className=\"gx-btn gx-sm gx-pri\"\n                    data-testid=\"brief-retry\"\n                    onClick={() => {\n                      const key = readyBriefInfo?.messageId ?? null;\n                      autoPreparedRef.current = key;\n                      setAttemptedBriefKey(key);\n                      setAutoPrepareFailed(false);\n                      void handlePreparePrompt().finally(() => setAutoPrepareFailed(true));\n                    }}\n                    disabled={generating}\n                  >\n                    {prepareError ? \"Réessayer\" : \"Rédiger le prompt\"}\n                    <ArrowRight className=\"gx-i\" />\n                  </button>\n              </div>\n              )}\n            </div>\n            {mods.length > 0 && (\n              <div className=\"gx-c3-mods\">\n                <span>Ou modifier :</span>\n                {mods.map((s) => (\n                  <button key={s} type=\"button\" className=\"gx-c3-mc\" onClick={() => handleSuggestion(s)} disabled={generating}>\n                    {s.replace(/^[\\p{Extended_Pictographic}️‍\\s]+/u, \"\")}\n                  </button>\n                ))}\n              </div>\n            )}\n            </>\n              );\n            })()}\n            </div>\n          )}\n"], ["{pending.length > 0 ? <div className=\"gx-tool-wait\" role=\"status\"><span className=\"gx-tool-dot\" aria-hidden />{PENDING_LABELS[pending[0]?.type ?? \"\"] ?? \"Travail en cours…\"}</div> : completedSteps", "{pending.length > 0 ? (waitLabel ? <div className=\"gx-tool-wait\" role=\"status\"><span className=\"gx-tool-dot\" aria-hidden />{waitLabel}</div> : null) : completedSteps"], ["  if (toolParts.length === 0 && pending.length === 0 && completedSteps.length === 0) return null;\n  return (\n    <div className=\"gx-tools\">", "  if (toolParts.length === 0 && pending.length === 0 && completedSteps.length === 0) return null;\n  // « Travail en cours… » générique seulement si la bulle a déjà du texte : sinon elle affiche\n  // déjà « Je réfléchis… » et les deux indicateurs se doublaient.\n  const hasText = parts.some((part) => part.type === \"text\" && String((part as { text?: unknown }).text ?? \"\").trim().length > 0);\n  const waitLabel = pending.length > 0 ? (PENDING_LABELS[pending[0]?.type ?? \"\"] ?? (hasText ? \"Travail en cours…\" : null)) : null;\n  return (\n    <div className=\"gx-tools\">"]]]]''')
CSS_FILE = "src/styles/gx-chat-v3.css"
CSS_MARK = "/* v41 : carte de rédaction du brief"
CSS = json.loads(r'''"/* v41 : carte de rédaction du brief, puces « Ou modifier », réflexion, listes du texte */\n.gx-chat3 .gx-c3-status{gap:6px}\n.gx-chat3 .gx-c3-run{background:var(--gx-c3-accent-soft);color:var(--gx-c3-accent-ink)}\n.gx-chat3 .gx-c3-run::before{content:\"\";width:6px;height:6px;border-radius:50%;background:currentColor;animation:gx-c3-dot 1.1s infinite}\n.gx-chat3 .gx-c3-ok{background:var(--gx-c3-ok-soft);color:var(--gx-c3-ok)}\n.gx-chat3 .gx-c3-err{background:var(--gx-c3-err-soft);color:var(--gx-c3-err)}\n.gx-chat3 .gx-c3-bcard{gap:14px;padding-bottom:16px}\n.gx-chat3 .gx-c3-bcard:has(>.gx-kf){padding-bottom:0}\n.gx-chat3 .gx-c3-bcard[data-phase=\"error\"] .gx-c3-head-icon{background:var(--gx-c3-err-soft);color:var(--gx-c3-err)}\n.gx-chat3 .gx-prompt>.gx-c3-detail{display:flex;align-items:flex-start;gap:8px;margin:0 16px;padding:10px 12px;border:1px solid color-mix(in srgb,var(--gx-c3-err) 25%,var(--gx-c3-line));border-radius:10px;background:var(--gx-c3-err-soft);color:var(--gx-c3-muted);font-size:13px;line-height:1.45}\n.gx-chat3 .gx-prompt>.gx-c3-detail .gx-i{width:15px;height:15px;flex:none;margin-top:1px;color:var(--gx-c3-err)}\n.gx-chat3 .gx-prompt>.gx-note{margin:0 16px;padding:9px 12px;border-radius:10px}\n.gx-chat3 .gx-prompt>.gx-note.gx-c3-slow{padding:0;background:none;color:var(--gx-c3-dim);font-weight:400;font-size:12.5px}\n.gx-chat3 .gx-prompt>.gx-pp.gx-pp-load{margin:0 16px}\n.gx-chat3 .gx-c3-mods{display:flex;flex-wrap:wrap;align-items:center;gap:6px;margin-top:10px}\n.gx-chat3 .gx-c3-mods>span{font-size:12.5px;color:var(--gx-c3-dim);margin-right:2px}\n.gx-chat3 .gx-c3-mc{display:inline-flex;align-items:center;gap:6px;height:30px;padding:0 11px;border:1px solid var(--gx-c3-line);border-radius:999px;background:var(--gx-c3-surface);font:500 13px var(--gx-c3-ui);color:var(--gx-c3-muted);cursor:pointer;max-width:100%;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.gx-chat3 .gx-c3-mc:hover{border-color:var(--gx-c3-line2);background:var(--gx-c3-raised);color:var(--gx-c3-fg)}\n.gx-chat3 .gx-c3-mc:disabled{opacity:.5;cursor:default}\n.gx-chat3 .gx-md ul,.gx-chat3 .gx-md ol{margin:4px 0 8px;padding-left:20px}\n.gx-chat3 .gx-md ul{list-style:disc}.gx-chat3 .gx-md ol{list-style:decimal}\n.gx-chat3 .gx-md li{margin:2px 0}.gx-chat3 .gx-md li::marker{color:var(--gx-c3-dim)}\n.gx-chat3 .gx-md li>p{margin:0}\n.gx-chat3 .gx-c3-sec header button{font-size:13px;font-weight:500;color:var(--gx-c3-accent-ink)}\n.gx-chat3 .gx-c3-scene summary>small{color:var(--gx-c3-accent-ink);font-weight:500}\n"''')
root = pathlib.Path(".")
ok = True; out = {}
for f, reps in R:
    s = (root / f).read_text()
    for old, new in reps:
        n = s.count(old)
        if n != 1:
            print(f"ÉCHEC {f}: trouvé {n} fois : {old[:90]!r}"); ok = False; continue
        s = s.replace(old, new)
    out[f] = s
cp = root / CSS_FILE; cs = cp.read_text()
if CSS_MARK in cs: print("ÉCHEC : CSS v41 déjà présent"); ok = False
if ok and not CHECK:
    for f, s in out.items(): (root / f).write_text(s)
    cp.write_text(cs.rstrip() + "\n" + CSS)
print("OK" if ok else "ÉCHEC", "(vérification seule)" if CHECK else "")
sys.exit(0 if ok else 1)
